//y = mx+b // x = (y-b)/m // y = m(x−Px)+Py // x = ((y-Py)/m)+Px
float line(in vec2 uv, in vec2 coord, float slope, float size){
    //doesn't play well with vertical or horizontal lines
    return 
    distance (uv, vec2 (
    ((uv.y-coord.y)/slope)+coord.x, 
    slope*(uv.x-coord.x)+coord.y)
    )
    <= size?1.0:.0;

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord)/(iResolution.xy);


    uv =( uv -.5 ) * 2.0; // UV to -1 to 1

    float ratio = iResolution.x/iResolution.y;
    uv.x = uv.x * (ratio);

    //uv = abs(uv); // apply symmetry
    //uv *= 5.0;

    float c = circle (uv, vec2(.10, .10), .2, .005);
    float p = point(uv, vec2(.10, .10), .01);
    float l = line(uv, vec2(.1, .1), 1.0, .0035);
    float k = length(vec2(.1, .2));
    //uv = abs(uv); // apply symmetry
    float v = p+l+c;
    // Output to screen
    //fragColor = vec4(uv, .0, .0);
    fragColor = vec4(v, v, v, .0);
}
